// ─── PAYMONGO CONFIG ──────────────────────────────────────────
// Replace with your PayMongo Public Key from:
// https://dashboard.paymongo.com → Developers → API Keys
const PAYMONGO_PUBLIC_KEY = 'pk_test_PUT_YOUR_PAYMONGO_PUBLIC_KEY_HERE';
// ─────────────────────────────────────────────────────────────

// Amount is in CENTAVOS (₱100 = 10000 centavos)
const AMOUNT = 10000;

export async function createGCashPayment(tagSlug, userEmail) {
  const encoded = btoa(PAYMONGO_PUBLIC_KEY + ':');

  // Step 1: Create a payment link via PayMongo Links API
  const res = await fetch('https://api.paymongo.com/v1/links', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Basic ${encoded}`,
    },
    body: JSON.stringify({
      data: {
        attributes: {
          amount: AMOUNT,
          description: `LOVER TAG — ${tagSlug} (${userEmail})`,
          remarks: `slug:${tagSlug}`,
        },
      },
    }),
  });

  if (!res.ok) {
    const err = await res.json();
    throw new Error(err?.errors?.[0]?.detail || 'PayMongo error');
  }

  const data = await res.json();
  const link = data?.data?.attributes?.checkout_url;
  const referenceNumber = data?.data?.attributes?.reference_number;
  return { checkoutUrl: link, referenceNumber };
}

// Poll PayMongo to check if a link has been paid
// You'd call this after redirect back from PayMongo
export async function checkPaymentStatus(referenceNumber) {
  const encoded = btoa(PAYMONGO_PUBLIC_KEY + ':');
  const res = await fetch(`https://api.paymongo.com/v1/links?reference_number=${referenceNumber}`, {
    headers: { Authorization: `Basic ${encoded}` },
  });
  const data = await res.json();
  const status = data?.data?.[0]?.attributes?.status;
  return status === 'paid';
}
